INSERT INTO tickets (id, title, description, status, priority, component, reporter, assignee, created_at, updated_at) VALUES
  (1, 'Checkout returns HTTP 500 when coupon is removed', 'POST /api/cart/checkout fails with 500 after the user applies and then removes a coupon. Stack trace shows TypeError: unsupported operand type(s) for -: ''float'' and ''NoneType'' in pricing/discounts.py apply_discount. Started after release 4.12.0.', 'open', 'P1', 'checkout', 'maria.lopez', 'dev.kim', '2026-10-21T09:12:00Z', '2026-10-21T09:12:00Z'),
  (2, 'Login redirect loop with expired session cookie', 'Users with an expired session cookie are redirected between /login and /dashboard indefinitely. Clearing cookies fixes it. Affects Safari 18 and Chrome 131. Middleware does not clear the stale cookie.', 'in_progress', 'P2', 'auth', 'tom.nguyen', 'ana.silva', '2026-10-18T14:03:00Z', '2026-10-18T14:03:00Z'),
  (3, 'Password reset emails not delivered for Outlook domains', 'Reset emails to outlook.com and hotmail.com addresses are never received. SMTP logs show 550 5.7.1 rejection: SPF check failed for mail-02 relay.', 'open', 'P1', 'notifications', 'support-bot', '', '2026-10-25T08:40:00Z', '2026-10-25T08:40:00Z'),
  (4, 'Search results page slow for queries with special characters', 'Search latency exceeds 8 seconds when the query contains ''&'' or ''%''. The ORM builds an unindexed LIKE query instead of using the full-text index.', 'open', 'P2', 'search', 'li.wei', '', '2026-10-12T17:20:00Z', '2026-10-12T17:20:00Z'),
  (5, 'Mobile app crashes on Android 15 when opening order history', 'NullPointerException in OrderHistoryAdapter.onBindViewHolder when an order has no shipping address (digital goods). Crash rate 2.3% of Android 15 sessions.', 'in_progress', 'P1', 'mobile', 'crashlytics', 'raj.patel', '2026-10-22T11:05:00Z', '2026-10-22T11:05:00Z'),
  (6, 'Inventory count goes negative under concurrent purchases', 'During the flash sale two customers bought the last unit of SKU HOM-502. inventory.quantity became -1. The decrement is done in application code after a separate SELECT, not atomically.', 'open', 'P0', 'inventory', 'ops-oncall', '', '2026-10-27T19:44:00Z', '2026-10-27T19:44:00Z'),
  (7, 'CSV export truncates rows after 10,000', 'Admin order export silently stops at 10,000 rows. Pagination loop exits when page size equals the hard-coded limit.', 'resolved', 'P2', 'admin', 'finance-team', 'dev.kim', '2026-09-30T10:00:00Z', '2026-09-30T10:00:00Z'),
  (8, 'Dark mode: unreadable text on payment form', 'In dark mode the card number placeholder is #222 on #1e1e1e background. Fails WCAG contrast.', 'open', 'P3', 'web-ui', 'designer.jo', '', '2026-10-10T13:30:00Z', '2026-10-10T13:30:00Z'),
  (9, 'API rate limiter blocks legitimate webhook retries', 'Payment provider webhook retries are rejected with 429 because the rate limiter keys on source IP and the provider uses a shared egress IP.', 'open', 'P2', 'payments', 'integrations', '', '2026-10-19T16:15:00Z', '2026-10-19T16:15:00Z'),
  (10, 'Session tokens logged in plaintext in access logs', 'The nginx access log format includes the full Authorization header. Tokens are visible to anyone with log access. Security issue.', 'in_progress', 'P0', 'security', 'sec-team', 'ana.silva', '2026-10-26T07:55:00Z', '2026-10-26T07:55:00Z'),
  (11, 'Coupon code field accepts expired coupons', 'Expired coupon SAVE20 is still accepted at checkout. The expiry check compares naive local time with UTC timestamps.', 'open', 'P2', 'checkout', 'qa.ben', '', '2026-10-15T12:00:00Z', '2026-10-15T12:00:00Z'),
  (12, 'Image uploads fail for HEIC files from iPhone', 'Uploading .heic product photos returns ''unsupported format''. Converter library lacks libheif.', 'open', 'P3', 'media', 'seller-support', '', '2026-10-05T09:25:00Z', '2026-10-05T09:25:00Z'),
  (13, 'Duplicate order confirmation emails', 'Some customers receive two confirmation emails. The email job is enqueued in both the order service and the payment webhook handler.', 'closed', 'P3', 'notifications', 'support-bot', 'dev.kim', '2026-09-20T15:00:00Z', '2026-09-20T15:00:00Z'),
  (14, 'Timeouts calling shipping rates API during peak hours', 'GET /shipping/rates times out after 30s at peak. No circuit breaker or cache; each cart refresh triggers a new external call.', 'open', 'P1', 'shipping', 'ops-oncall', '', '2026-10-24T18:10:00Z', '2026-10-24T18:10:00Z'),
  (15, 'Checkout total wrong when gift card and coupon combined', 'Applying a gift card after a percentage coupon double-counts the discount. Rounding happens before the coupon is applied.', 'open', 'P1', 'checkout', 'qa.ben', '', '2026-10-23T10:45:00Z', '2026-10-23T10:45:00Z'),
  (16, 'Memory leak in recommendation worker', 'Worker RSS grows 200MB/hour until OOM-killed. Heap snapshot shows an unbounded LRU cache keyed by session id.', 'open', 'P2', 'recommendations', 'sre.mia', '', '2026-10-16T20:30:00Z', '2026-10-16T20:30:00Z');
INSERT INTO comments (ticket_id, author, body, created_at) VALUES
  (2, 'ana.silva', 'Reproduced locally. Middleware returns redirect before checking cookie expiry.', '2026-10-19T09:00:00Z'),
  (6, 'ops-oncall', 'Manually corrected stock. Need atomic UPDATE ... WHERE quantity >= n.', '2026-10-27T20:10:00Z');
